// Fan out one review request per model.
const diff = $json.diff || '';
const models = String($json.models || 'openai/gpt-6-luna').split(',').map((s) => s.trim()).filter(Boolean);
const system = "You are an independent, read-only PR reviewer. Review the diff against this checklist: correctness and intent; tests and evidence; docs updated in the same commit; scope and contracts; simplicity and anti-slop; harness changes; boundaries (no credentials). Cite path:line; separate verified from inference. Do not approve or merge. Output: first line VERDICT: approve | request-changes | comment; then CHECKLIST: item=pass|fail|n-a; then FINDINGS: - [severity] path:line - problem / fix.";
return models.map((m) => ({ json: { model: m, body: JSON.stringify({ model: m, messages: [ { role: 'system', content: system }, { role: 'user', content: 'Diff: ' + diff } ] }) } }));

const reqs = $('Prepare requests').all();
const results = $input.all();
const parsed = results.map((it, i) => {
  const c = (it.json.choices && it.json.choices[0] && it.json.choices[0].message && it.json.choices[0].message.content) || '';
  const vl = c.split('\n').find((l) => /VERDICT\s*:/i.test(l)) || '';
  const verdict = /request-changes/i.test(vl) ? 'request-changes' : /approve/i.test(vl) ? 'approve' : 'comment';
  const model = (reqs[i] && reqs[i].json && reqs[i].json.model) || (it.json.model || ('model-' + i));
  return { model, verdict, content: c };
});
const anyChanges = parsed.some((r) => r.verdict === 'request-changes');
const allApprove = parsed.length > 0 && parsed.every((r) => r.verdict === 'approve');
const verdict = anyChanges ? 'request-changes' : allApprove ? 'approve' : 'comment';
const disagreement = new Set(parsed.map((r) => r.verdict)).size > 1;
const comment = '**Ensemble verdict: ' + verdict + (disagreement ? ' (judges disagreed)' : '') + '**\n\n' + parsed.map((r) => '### ' + r.model + ' - ' + r.verdict + '\n' + r.content).join('\n\n');
return [{ json: { verdict, disagreement, judgeCount: parsed.length, comment } }];
